#!/bin/bash
#####################################################################################################################
# paramedir.sh
# Brief: This script runs paramedir using the traces generated by the extrae.sh script
#####################################################################################################################

###################
# AS variables
###################
run_root=%COMMON_PATH_LOCATIONS.RUN_ROOT%
project=%COMMON_PATH_LOCATIONS.PROJECT_ROOT%
analysis_tools=${project}/cfg/trace_analysis/
cfg=%COMMON_PATH_LOCATIONS.CFG%
platform=%DEFAULT.HPCARCH%
platform=${platform,,}
env_sources=${cfg}/env/${platform}/environment.env

# shellcheck source=proj/auto-performance-profiling/cfg/utils/bash/utils.sh
. ${cfg}/utils/bash/utils.sh

components=($(bashify_array "%MODEL.REPORT_COMPONENTS%" true))
tests=($(bashify_array "%TRACING.TEST_NAMES%" true))
names=($(bashify_array "%TRACING.NAMES%" true))

###################
# Start script
###################

source ${env_sources}

member="tracing"
paramedir_configurations=$(find ${analysis_tools}/paramedir_configurations/*)

for test in ${tests[@]}
do
    test_folder=${run_root}/${member}/${test}
    mkdir -p  ${test_folder}/paramedir

    cd "${test_folder}/paramedir" || exit
    rm -f *.pm

    for name in "${names[@]}"
    do
        trace_folder=${test_folder}/run_${name}
        [ -f ${trace_folder}/job_geometry.sh ] && . ${trace_folder}/job_geometry.sh
        basename_trace_folder=$(basename ${trace_folder})
        trace_id=$(echo ${basename_trace_folder} | sed -e 's/run_//')

        for component in "${components[@]}"; do
            trace=${trace_folder}/${component}.best_cut.prv

            threads_to_ignore=""
            ! [ -z ${job_geometry[@]} ] && create_threads_to_ignore ${component}

            for cfg in $paramedir_configurations 
            do
                cp ${cfg} .
                mod_cfg=$(basename ${cfg})

                [ "${threads_to_ignore}" != "" ] && sed -i "s/window_object appl { 1, { All } }/${threads_to_ignore}/" ${mod_cfg}

                paramedir ${trace} ${mod_cfg} 
                cfg_extension=${cfg#*.}
                cfg_name=${cfg##*/}
                cfg_name=${cfg_name%.${cfg_extension}}
                if [[ ${cfg_extension} == "pm.cfg" ]] 
                then
                    mv ${cfg_name}.pm ${component}-${trace_id}-${cfg_name}.pm
                else
                    mv ${cfg_name} ${component}-${trace_id}-${cfg_name}.csv
                fi
            done
        done
    done
done

